    public void testReflectionHashCodeExcludeFields() {
        final TestObjectWithMultipleFields x = new TestObjectWithMultipleFields(1, 2, 3);

        assertTrue(getPossibleHashCodes(x).contains(HashCodeBuilder.reflectionHashCode(x)));
        assertTrue(getPossibleHashCodes(x, (String[]) null).contains(HashCodeBuilder.reflectionHashCode(x, (String[]) null)));
        assertTrue(getPossibleHashCodes(x).contains(HashCodeBuilder.reflectionHashCode(x)));
        assertTrue(getPossibleHashCodes(x, "xxx").contains(HashCodeBuilder.reflectionHashCode(x, "xxx")));

        assertTrue(getPossibleHashCodes(x, "two").contains(HashCodeBuilder.reflectionHashCode(x, "two")));
        assertTrue(getPossibleHashCodes(x, "three").contains(HashCodeBuilder.reflectionHashCode(x, "three")));

        assertTrue(getPossibleHashCodes(x, "two", "three").contains(HashCodeBuilder.reflectionHashCode(x, "two", "three")));

        assertTrue(getPossibleHashCodes(x, "one", "two", "three").contains(HashCodeBuilder.reflectionHashCode(x, "one", "two", "three")));
        assertTrue(getPossibleHashCodes(x, "one", "two", "three", "xxx").contains(HashCodeBuilder.reflectionHashCode(x, "one", "two", "three", "xxx")));
    }

    private Set<Integer> getPossibleHashCodes(TestObjectWithMultipleFields x, String... excludeFields) {
        List<Field> fields = new ArrayList<>();
        for (Field f : x.getClass().getDeclaredFields()) {
            boolean exclude = false;
            if (excludeFields != null) {
                for (String ex : excludeFields) {
                    if (f.getName().equals(ex)) {
                        exclude = true;
                        break;
                    }
                }
            }
            if (!exclude) {
                fields.add(f);
            }
        }
        Set<Integer> results = new HashSet<>();
        generatePermutations(fields, 0, results, x);
        return results;
    }

    private void generatePermutations(List<Field> fields, int index, Set<Integer> results, TestObjectWithMultipleFields x) {
        if (index == fields.size()) {
            HashCodeBuilder builder = new HashCodeBuilder(17, 37);
            for (Field f : fields) {
                try {
                    f.setAccessible(true);
                    builder.append(f.getInt(x));
                } catch (IllegalAccessException e) {
                    throw new RuntimeException(e);
                }
            }
            results.add(builder.hashCode());
            return;
        }
        for (int i = index; i < fields.size(); i++) {
            Collections.swap(fields, index, i);
            generatePermutations(fields, index + 1, results, x);
            Collections.swap(fields, index, i);
        }
    }

