    java.util.function.Function<Schema, Schema> sortFields = s -> {
        List<Schema.Field> fields = new ArrayList<>(s.getFields());
        fields.sort(Comparator.comparing(Schema.Field::name));
        List<Schema.Field> newFields = new ArrayList<>();
        for (Schema.Field f : fields) {
            Schema.Field nf = new Schema.Field(f.name(), f.schema(), f.doc(), f.defaultVal());
            nf.setOrder(f.order());
            for (String alias : f.aliases()) nf.addAlias(alias);
            for (Map.Entry<String, Object> e : f.getObjectProps().entrySet()) nf.addProp(e.getKey(), e.getValue());
            newFields.add(nf);
        }
        Schema ns = Schema.createRecord(s.getName(), s.getDoc(), s.getNamespace(), s.isError());
        ns.setFields(newFields);
        for (String alias : s.getAliases()) ns.addAlias(alias);
        for (Map.Entry<String, Object> e : s.getObjectProps().entrySet()) ns.addProp(e.getKey(), e.getValue());
        return ns;
    };

    assertEquals(sortFields.apply(expected).toString(), sortFields.apply(actual).toString());
  }

